import 'package:flutter/material.dart';import '../services/database_service.dart';
class PanenScreen extends StatefulWidget{const PanenScreen({super.key});@override State<PanenScreen>createState()=>_P();}
class _P extends State<PanenScreen>{final db=DB.i;List<Map<String,dynamic>> rows=[];@override void initState(){super.initState();load();}Future<void>load()async{final r=await db.all('panen');if(mounted)setState(()=>rows=r);}Future<void>add()async{final blocks=await db.all('blok');if(blocks.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Tambahkan Blok terlebih dahulu.')));return;}final x=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>PanenForm(blocks:blocks));if(x!=null){await(await db.db).insert('panen',x);load();}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Panen')),body:RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:rows.length,itemBuilder:(_,i){final r=rows[i];return ListTile(leading:const Icon(Icons.agriculture),title:Text('${r['tanggal']} • ${r['total_jjg']} janjang'),subtitle:Text('Estimasi ${r['estimasi_kg']} kg'));})),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Input Panen')));}
class PanenForm extends StatefulWidget{final List<Map<String,dynamic>> blocks;const PanenForm({super.key,required this.blocks});@override State<PanenForm>createState()=>_F();}
class _F extends State<PanenForm>{int? block;final jjg=TextEditingController(),kg=TextEditingController();@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Input Panen'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:block,decoration:const InputDecoration(labelText:'Blok'),items:widget.blocks.map((b)=>DropdownMenuItem(value:b['id']as int,child:Text('${b['kode']} ${b['nama']??''}'))).toList(),onChanged:(v)=>setState(()=>block=v)),TextField(controller:jjg,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Jumlah janjang')),TextField(controller:kg,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Estimasi kg'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:(){if(block==null||jjg.text.isEmpty)return;final n=DateTime.now();Navigator.pop(context,{'tanggal':'${n.year}-${n.month.toString().padLeft(2,'0')}-${n.day.toString().padLeft(2,'0')}','blok_id':block,'total_jjg':int.tryParse(jjg.text)??0,'estimasi_kg':double.tryParse(kg.text)??0,'status':'selesai'});},child:const Text('Simpan'))]);}}
